-  return binary_fuse_murmur64(key + seed);
+  uint64_t lo;
+  uint64_t hi = binary_fuse_mulhilo(key, seed, &lo);
+  uint64_t h = (lo ^ hi) * UINT64_C(0xc4ceb9fe1a85ec53);
+  h ^= h >> 33U;
+  return h;
 }
