+/**
+ * Layout. A key with hash h has three locations, one in each of three
+ * consecutive segments:
+ *   h0 = mulhi(h, SegmentCountLength)
+ *   h1 = (h0 + SegmentLength) ^ ((h >> 18) & (SegmentLength - 1))
+ *   h2 = (h0 + 2 * SegmentLength) ^ (h & (SegmentLength - 1))
+ * The fingerprint is taken from the top bits of the low half of the product
+ * h * SegmentCountLength: these are the bits right below h0, which are
+ * uniform and independent of h0 and of the in-segment offsets.
+ **/
+typedef struct binary_hashes_s {
+  uint32_t h0;
+  uint32_t h1;
+  uint32_t h2;
+} binary_hashes_t;
+
+static inline binary_hashes_t binary_fuse_hash_batch(uint64_t hash,
+    uint32_t segment_count_length, uint32_t segment_length, uint64_t *lo) {
+  binary_hashes_t ans;
+  uint32_t mask = segment_length - 1;
+  ans.h0 = (uint32_t)binary_fuse_mulhilo(hash, segment_count_length, lo);
+  ans.h1 = (ans.h0 + segment_length) ^ ((uint32_t)(hash >> 18U) & mask);
+  ans.h2 = (ans.h0 + 2 * segment_length) ^ ((uint32_t)hash & mask);
+  return ans;
+}
