+/**
+ * Construction.
+ *
+ * Every attempt hashes the keys with a fresh seed and builds, for each
+ * location, the number of keys that map to it and the xor of their hashes.
+ * Then it peels: a location with a single key determines that key, which is
+ * removed from its other two locations, possibly leaving more singletons.
+ * The peeled locations are queued in a FIFO that also records the peeling
+ * order; each peeled location keeps the hash of its key, so the fingerprints
+ * can then be assigned in reverse peeling order.
+ *
+ * Small inputs are added in input order and peeled in a left-to-right sweep
+ * over the table. Large inputs are first bucketed by the segment of their
+ * first location; segment s is complete once bucket s has been added, so
+ * adding and peeling proceed together, segment by segment, within a small
+ * window of the table that stays in cache.
+ **/
+typedef struct binary_fuse_builder_s {
+  uint64_t *xors;    // xor of the hashes mapped to each location
+  uint8_t *counts;   // number of keys mapped to each location (mod 256)
+  uint32_t *order;   // peeling queue, which also records the peeling order
+  uint64_t *sorted;  // hashes bucketed by segment (large inputs only)
+  uint32_t *bucket;  // bucket sizes and offsets (large inputs only)
+  void *memory;
+  uint32_t *extra;   // separate queue, if the shared one could run short
+  uint32_t capacity; // bucket capacity (0: always count the buckets first)
+  uint32_t peeled;
+  uint32_t queued;
+} binary_fuse_builder_t;

