+  size_t m = array_length;
+  bool sorted = (size_t)array_length * 9 > BINARY_FUSE_SORT_THRESHOLD;
+  // Buckets get a fixed capacity, six standard deviations above their
+  // expected size, so that the hashes can be scattered in a single pass.
+  double mean = (double)size / segment_count;
+  size_t capacity = (size_t)(mean + 6 * sqrt(mean)) + 16;
+  // the order buffer needs array_length + 3 entries (slack for branchless pushes)
+  size_t order_bytes = (m + 3) * sizeof(uint32_t);
+  size_t sorted_bytes = 0;
+  if (sorted) {
