diff --git a/include/binaryfuse_api.h b/include/binaryfuse_api.h
new file mode 100644
index 0000000..5f465e9
--- /dev/null
+++ b/include/binaryfuse_api.h
@@ -0,0 +1,216 @@
+// Included for each public fingerprint width by binaryfusefilter.h.
+static inline bool BF_NAME(contain)(uint64_t key, const BF_TYPE *filter) {
+  uint64_t fields = filter->HashFields;
+  if (!fields) {
+    uint64_t h = binary_fuse_mix_split(key, filter->Seed);
+    binary_hashes_t idx = BF_NAME(hash_batch)(h, filter);
+    return BF_NAME(fingerprint)(h) == (filter->Fingerprints[idx.h0] ^
+        filter->Fingerprints[idx.h1] ^ filter->Fingerprints[idx.h2]);
+  }
+  uint64_t hash = binary_fuse_band_hash(key, filter->Seed);
+  size_t start = binary_fuse_band_start(hash, filter->SegmentCountLength);
+  const BF_WORD *p = filter->Fingerprints + start;
+  uint64_t bits = hash & fields;
+  return (BF_WORD)(bits >> 32) == (p[0] ^ p[1 + (uint16_t)bits] ^
+      p[filter->SegmentCount + (uint16_t)(bits >> 16)]);
+}
+
+static inline void BF_NAME(set_layout)(BF_TYPE *filter, uint32_t size,
+                                       const binary_fuse_layout *layout) {
+  filter->Size = size;
+  filter->SegmentLength = layout->span;
+  filter->SegmentLengthMask = layout->span - 1;
+  filter->SegmentCount = layout->bias;
+  filter->SegmentCountLength = layout->range;
+  filter->ArrayLength = layout->length;
+}
+
+// Allocate capacity for up to size keys. Release it with the matching free.
+static inline bool BF_NAME(allocate)(uint32_t size, BF_TYPE *filter) {
+  binary_fuse_layout layout;
+  memset(filter, 0, sizeof(*filter));
+  if (!binary_fuse_band_layout(size, &layout)) return false;
+  BF_NAME(set_layout)(filter, size, &layout);
+  filter->Seed = BINARY_FUSE_INITIAL_MULTIPLIER;
+  filter->HashFields = binary_fuse_fields(layout.span, UINT16_MAX);
+  filter->Fingerprints = (BF_WORD *)calloc(layout.length, sizeof(BF_WORD));
+  return filter->Fingerprints != NULL;
+}
+
+static inline size_t BF_NAME(size_in_bytes)(const BF_TYPE *filter) {
+  return sizeof(*filter) + (size_t)filter->ArrayLength * sizeof(BF_WORD);
+}
+
+static inline void BF_NAME(free)(BF_TYPE *filter) {
+  free(filter->Fingerprints);
+  memset(filter, 0, sizeof(*filter));
+}
+
+static inline bool BF_NAME(build)(uint64_t *keys, uint32_t size, BF_TYPE *filter) {
+  uint64_t seed, fields;
+  if (!binary_fuse_band_build(keys, size, &seed, filter->SegmentCountLength,
+          filter->SegmentLength, filter->SegmentCount, filter->Fingerprints,
+          sizeof(BF_WORD), &fields)) return false;
+  filter->Seed = seed;
+  filter->HashFields = fields;
+  return true;
+}
+
+static inline bool BF_NAME(populate)(uint64_t *keys, uint32_t size, BF_TYPE *filter) {
+  if (size > filter->Size || !filter->Fingerprints) return false;
+  if (filter->HashFields) return BF_NAME(build)(keys, size, filter);
+
+  // Repopulation of a deserialized original-format filter needs the new layout.
+  BF_TYPE fresh;
+  if (!BF_NAME(allocate)(filter->Size, &fresh)) return false;
+  if (!BF_NAME(build)(keys, size, &fresh)) {
+    BF_NAME(free)(&fresh);
+    return false;
+  }
+  BF_NAME(free)(filter);
+  *filter = fresh;
+  return true;
+}
+
+static inline size_t BF_NAME(serialization_bytes)(const BF_TYPE *filter) {
+  return BINARY_FUSE_HEADER_BYTES + (size_t)filter->ArrayLength * sizeof(BF_WORD);
+}
+
+static inline char *BF_NAME(write_header)(const BF_TYPE *filter, char *buffer) {
+  uint32_t span = filter->SegmentLength, count = filter->SegmentCount;
+  if (filter->HashFields) {
+    span |= BINARY_FUSE_WIRE_FLAG;
+    count |= (uint32_t)(filter->HashFields >> 32) << 16;
+  }
+  const uint32_t words[5] = { filter->Size, span, count,
+                              filter->SegmentCountLength, filter->ArrayLength };
+  memcpy(buffer, &filter->Seed, sizeof(filter->Seed));
+  memcpy(buffer + sizeof(filter->Seed), words, sizeof(words));
+  return buffer + BINARY_FUSE_HEADER_BYTES;
+}
+
+// Native endian. Allocate serialization_bytes(filter) bytes for the buffer.
+static inline void BF_NAME(serialize)(const BF_TYPE *filter, char *buffer) {
+  char *data = BF_NAME(write_header)(filter, buffer);
+  memcpy(data, filter->Fingerprints, (size_t)filter->ArrayLength * sizeof(BF_WORD));
+}
+
+// No allocation. The returned address is the start of the fingerprint data.
+static inline const char *BF_NAME(deserialize_header)(BF_TYPE *filter, const char *buffer) {
+  uint32_t words[5];
+  memcpy(&filter->Seed, buffer, sizeof(filter->Seed));
+  memcpy(words, buffer + sizeof(filter->Seed), sizeof(words));
+  filter->Size = words[0];
+  filter->SegmentLength = words[1] & ~BINARY_FUSE_WIRE_FLAG;
+  filter->SegmentLengthMask = filter->SegmentLength - 1;
+  filter->SegmentCount = words[2];
+  filter->HashFields = 0;
+  if (words[1] & BINARY_FUSE_WIRE_FLAG) {
+    filter->SegmentCount = (uint16_t)words[2];
+    filter->HashFields = binary_fuse_fields(filter->SegmentLength, words[2] >> 16);
+  }
+  filter->SegmentCountLength = words[3];
+  filter->ArrayLength = words[4];
+  return buffer + BINARY_FUSE_HEADER_BYTES;
+}
+
+static inline bool BF_NAME(valid_header)(const BF_TYPE *filter) {
+  uint32_t span = filter->SegmentLength;
+  if (filter->Size > filter->ArrayLength) return false;
+  if (!span || (span & (span - 1)) || !filter->SegmentCountLength) return false;
+  uint64_t halo;
+  if (filter->HashFields) {
+    if (span > 4096 || filter->SegmentCount <= span) return false;
+    halo = (uint64_t)filter->SegmentCount + span - 1;
+    if (halo >= 32768) return false;
+  } else {
+    halo = (uint64_t)span * 2;
+    if ((uint64_t)span * filter->SegmentCount != filter->SegmentCountLength) return false;
+  }
+#if SIZE_MAX < UINT64_MAX
+  if ((uint64_t)filter->ArrayLength * sizeof(BF_WORD) > SIZE_MAX) return false;
+#endif
+  return (uint64_t)filter->SegmentCountLength + halo == filter->ArrayLength;
+}
+
+static inline bool BF_NAME(deserialize)(BF_TYPE *filter, const char *buffer) {
+  const char *data = BF_NAME(deserialize_header)(filter, buffer);
+  filter->Fingerprints = NULL;
+  if (!BF_NAME(valid_header)(filter)) return false;
+  size_t bytes = (size_t)filter->ArrayLength * sizeof(BF_WORD);
+  filter->Fingerprints = (BF_WORD *)malloc(bytes);
+  if (!filter->Fingerprints) return false;
+  memcpy(filter->Fingerprints, data, bytes);
+  return true;
+}
+
+static inline size_t BF_NAME(pack_bytes)(const BF_TYPE *filter) {
+  size_t header = sizeof(uint64_t) + sizeof(uint32_t);
+  if (filter->HashFields) header += BINARY_FUSE_HEADER_BYTES;
+  size_t bytes = header + ((size_t)filter->ArrayLength + 7) / 8;
+  for (size_t i = 0; i < filter->ArrayLength; ++i)
+    if (filter->Fingerprints[i]) bytes += sizeof(BF_WORD);
+  return bytes;
+}
+
+static inline size_t BF_NAME(pack)(const BF_TYPE *filter, char *buffer, size_t space) {
+  // A size-zero prefix with a complete, marked header distinguishes the new
+  // encoding from the shorter original packing of an empty filter.
+  uint64_t seed = filter->HashFields ? BINARY_FUSE_PACK_MAGIC : filter->Seed;
+  uint32_t size = filter->HashFields ? 0 : filter->Size;
+  size_t prefix = sizeof(seed) + sizeof(size);
+  size_t header = prefix + (filter->HashFields ? BINARY_FUSE_HEADER_BYTES : 0);
+  size_t bitmap_bytes = ((size_t)filter->ArrayLength + 7) / 8;
+  if (space < header || space - header < bitmap_bytes) return 0;
+  memcpy(buffer, &seed, sizeof(seed));
+  memcpy(buffer + sizeof(seed), &size, sizeof(size));
+  if (filter->HashFields) BF_NAME(write_header)(filter, buffer + prefix);
+  uint8_t *bitmap = (uint8_t *)buffer + header;
+  memset(bitmap, 0, bitmap_bytes);
+  size_t pos = header + bitmap_bytes;
+  for (size_t i = 0; i < filter->ArrayLength; ++i) {
+    BF_WORD value = filter->Fingerprints[i];
+    if (!value) continue;
+    if (space - pos < sizeof(value)) return 0;
+    bitmap[i / 8] |= (uint8_t)(1u << (i % 8));
+    memcpy(buffer + pos, &value, sizeof(value));
+    pos += sizeof(value);
+  }
+  return pos;
+}
+
+static inline bool BF_NAME(unpack)(BF_TYPE *filter, const char *buffer, size_t len) {
+  uint64_t seed;
+  uint32_t size;
+  size_t pos = sizeof(seed) + sizeof(size);
+  memset(filter, 0, sizeof(*filter));
+  if (len < pos) return false;
+  memcpy(&seed, buffer, sizeof(seed));
+  memcpy(&size, buffer + sizeof(seed), sizeof(size));
+  if (seed == BINARY_FUSE_PACK_MAGIC && size == 0 && len - pos >= BINARY_FUSE_HEADER_BYTES) {
+    BF_NAME(deserialize_header)(filter, buffer + pos);
+    if (!filter->HashFields || !BF_NAME(valid_header)(filter)) return false;
+    pos += BINARY_FUSE_HEADER_BYTES;
+  } else {
+    binary_fuse_layout layout;
+    if (!binary_fuse_original_layout(size, &layout)) return false;
+    BF_NAME(set_layout)(filter, size, &layout);
+    filter->Seed = seed;
+  }
+  size_t bitmap_bytes = ((size_t)filter->ArrayLength + 7) / 8;
+  if (len - pos < bitmap_bytes) return false;
+  const uint8_t *bitmap = (const uint8_t *)buffer + pos;
+  pos += bitmap_bytes;
+  filter->Fingerprints = (BF_WORD *)calloc(filter->ArrayLength, sizeof(BF_WORD));
+  if (!filter->Fingerprints) return false;
+  for (size_t i = 0; i < filter->ArrayLength; ++i) {
+    if (!(bitmap[i / 8] & (1u << (i % 8)))) continue;
+    if (len - pos < sizeof(BF_WORD)) {
+      BF_NAME(free)(filter);
+      return false;
+    }
+    memcpy(&filter->Fingerprints[i], buffer + pos, sizeof(BF_WORD));
+    pos += sizeof(BF_WORD);
+  }
+  return true;
+}
