index 0000000..8744717
--- /dev/null
+++ b/include/binaryfuse_build.h
@@ -0,0 +1,294 @@
+#ifndef BINARYFUSE_BUILD_H
+#define BINARYFUSE_BUILD_H
+
+// All three cells are within 32768 positions of each other. Two 16-bit
+// coordinates, a 16-bit tag and a 16-bit degree fit in one accumulator.
+// Addition and subtraction recover the exact record when the degree is one.
+static inline uint64_t binary_fuse_incidence(uint32_t next, uint32_t previous,
+                                              uint32_t tag_bits) {
+  return ((uint64_t)(uint16_t)previous << 48) |
+         ((uint64_t)(uint16_t)next << 32) | tag_bits | 1;
+}
+
+static inline uint32_t binary_fuse_neighbor(uint32_t pivot, uint16_t low,
+                                            bool short_table) {
+  if (short_table) return low;
+  int16_t delta = (int16_t)(uint16_t)(low - pivot);
+  return (uint32_t)((int64_t)pivot + delta);
+}
+
+static inline void binary_fuse_add_edge(uint64_t *cells, uint32_t a, uint64_t bits,
+                                        uint32_t mask, uint32_t bias) {
+  uint32_t b = a + 1 + ((uint32_t)bits & mask);
+  uint32_t c = a + bias + ((uint32_t)(bits >> 16) & mask);
+  uint32_t tag = (uint32_t)(bits >> 16) & UINT32_C(0xffff0000);
+  cells[a] += binary_fuse_incidence(b, c, tag);
+  cells[b] += binary_fuse_incidence(c, a, tag);
+  cells[c] += binary_fuse_incidence(a, b, tag);
+}
+
+#define BINARY_FUSE_TILE_BITS 12
+#define BINARY_FUSE_TILE (1u << BINARY_FUSE_TILE_BITS)
+
+// Temporarily use each tile of the accumulator array as a bin of input edges.
+// Edges point right, so we can replace bins by their final accumulators in
+// descending tile order. Dense bins spill into the as-yet unused peel queue.
+static inline void binary_fuse_fill_tiled(const uint64_t *keys, uint32_t n, uint64_t seed,
+    uint32_t range, uint32_t length, uint32_t mask, uint32_t bias, uint64_t *cells,
+    uint32_t *overflow, uint32_t *used, uint32_t tiles, uint64_t *scratch) {
+  uint32_t spilled = 0;
+  memset(used, 0, (size_t)tiles * sizeof(*used));
+  for (uint32_t i = 0; i < n; ++i) {
+    uint64_t hash = binary_fuse_band_hash(keys[i], seed);
+    uint32_t a = binary_fuse_band_start(hash, range);
+    uint32_t tile = a >> BINARY_FUSE_TILE_BITS;
+    uint32_t base = a & ~(BINARY_FUSE_TILE - 1);
+    uint32_t pos = used[tile];
+    if (pos < BINARY_FUSE_TILE && pos < length - base) {
+      cells[base + pos] = ((uint64_t)a << 48) | (hash & UINT64_C(0xffffffffffff));
+      used[tile] = pos + 1;
+    } else {
+      overflow[spilled++] = i;
+    }
+  }
+
+  size_t end = (size_t)tiles * BINARY_FUSE_TILE;
+  if (end < length) memset(cells + end, 0, (length - end) * sizeof(*cells));
+  for (uint32_t tile = tiles; tile-- > 0;) {
+    uint32_t base = tile << BINARY_FUSE_TILE_BITS;
+    size_t capacity = length - base;
+    if (capacity > BINARY_FUSE_TILE) capacity = BINARY_FUSE_TILE;
+    memcpy(scratch, cells + base, used[tile] * sizeof(*scratch));
+    memset(cells + base, 0, capacity * sizeof(*cells));
+    for (uint32_t i = 0; i < used[tile]; ++i) {
+      uint64_t edge = scratch[i];
+      uint32_t a = base | ((uint32_t)(edge >> 48) & (BINARY_FUSE_TILE - 1));
+      binary_fuse_add_edge(cells, a, edge, mask, bias);
+    }
+  }
+  for (uint32_t i = 0; i < spilled; ++i) {
+    uint64_t hash = binary_fuse_band_hash(keys[overflow[i]], seed);
+    binary_fuse_add_edge(cells, binary_fuse_band_start(hash, range), hash, mask, bias);
+  }
+}
+
+static inline void binary_fuse_remove_incidence(uint64_t *cells, uint32_t vertex,
+    uint64_t record, uint32_t *queue, uint32_t *end) {
+  uint64_t updated = cells[vertex] - record;
+  cells[vertex] = updated;
+  queue[*end] = vertex;
+  *end += (uint16_t)updated == 1;
+}
+
+// A vertex enters the queue only as its degree crosses one. Compact live
+// pivots into the consumed prefix. Their records stay in place for backfill.
+#define BINARY_FUSE_LOOKAHEAD 16
+
+static inline uint32_t binary_fuse_peel(uint64_t *cells, uint32_t *queue,
+                                        uint32_t end, bool short_table) {
+  uint32_t count = 0;
+  for (uint32_t i = 0; i < end; ++i) {
+#if defined(__GNUC__) || defined(__clang__)
+    if (!short_table && end - i > BINARY_FUSE_LOOKAHEAD)
+      __builtin_prefetch(cells + queue[i + BINARY_FUSE_LOOKAHEAD], 0, 1);
+#endif
+    uint32_t pivot = queue[i];
+    uint64_t record = cells[pivot];
+    if ((uint16_t)record != 1) continue;
+    uint32_t b = binary_fuse_neighbor(pivot, (uint16_t)(record >> 32), short_table);
+    uint32_t c = binary_fuse_neighbor(pivot, (uint16_t)(record >> 48), short_table);
+    uint32_t tag = (uint32_t)record & UINT32_C(0xffff0000);
+    binary_fuse_remove_incidence(cells, b, binary_fuse_incidence(c, pivot, tag), queue, &end);
+    binary_fuse_remove_incidence(cells, c, binary_fuse_incidence(pivot, b, tag), queue, &end);
+    queue[count++] = pivot;
+  }
+  return count;
+}
+
+static inline unsigned binary_fuse_low_bit(uint64_t bits) {
+#if defined(__GNUC__) || defined(__clang__)
+  return (unsigned)__builtin_ctzll(bits);
+#else
+  unsigned i = 0;
+  while (!(bits & 1)) { bits >>= 1; ++i; }
+  return i;
+#endif
+}
+
+static inline unsigned binary_fuse_bit_count(uint32_t bits) {
+#if defined(__GNUC__) || defined(__clang__)
+  return (unsigned)__builtin_popcount(bits);
+#else
+  unsigned n = 0;
+  while (bits) { bits &= bits - 1; ++n; }
+  return n;
+#endif
+}
+
+#define BINARY_FUSE_CORE_LIMIT 12
+
+// Dependent equations (in particular two keys with identical vertices) can
+// disagree in a few tag planes. Set the target to zero in those planes and
+// choose uniformly distributed free variables there. Lookup uses the same
+// projection, and still compares every output bit.
+static inline bool binary_fuse_solve_core(const uint64_t *keys, uint32_t n, uint64_t seed,
+    uint32_t range, uint32_t mask, uint32_t bias, const uint64_t *cells,
+    void *fingerprints, size_t width, uint64_t *fields, uint32_t remaining) {
+  uint32_t columns[3 * BINARY_FUSE_CORE_LIMIT];
+  uint64_t basis[3 * BINARY_FUSE_CORE_LIMIT] = {0};
+  unsigned num_columns = 0, num_rows = 0;
+  uint32_t full = width == 1 ? UINT8_MAX : UINT16_MAX;
+  uint32_t keep = full;
+  for (uint32_t i = 0; i < n; ++i) {
+    uint64_t hash = binary_fuse_band_hash(keys[i], seed);
+    uint32_t a = binary_fuse_band_start(hash, range);
+    uint32_t b = a + 1 + ((uint32_t)hash & mask);
+    uint32_t c = a + bias + ((uint32_t)(hash >> 16) & mask);
+    // Every residual vertex has degree at least two. Peeled pivots retain
+    // their degree-one records for backfill.
+    if ((uint16_t)cells[a] < 2 || (uint16_t)cells[b] < 2 || (uint16_t)cells[c] < 2) continue;
+    if (++num_rows > remaining) return false;
+    uint32_t ids[3] = {a, b, c};
+    uint64_t row = (uint16_t)(hash >> 32);
+    for (unsigned j = 0; j < 3; ++j) {
+      unsigned col = 0;
+      while (col < num_columns && columns[col] != ids[j]) ++col;
+      if (col == num_columns) columns[num_columns++] = ids[j];
+      row ^= UINT64_C(1) << (16 + col);
+    }
+    while (row >> 16) {
+      unsigned col = binary_fuse_low_bit(row >> 16);
+      if (!basis[col]) {
+        basis[col] = row;
+        break;
+      }
+      row ^= basis[col];
+    }
+    if (!(row >> 16)) keep &= ~(uint32_t)row;
+  }
+  if (num_rows != remaining || binary_fuse_bit_count(keep) < 2 * width) return false;
+
+  *fields = binary_fuse_fields(mask + 1, keep);
+  if (keep != full) {
+    uint64_t lanes = width == 1 ? UINT64_C(0x0101010101010101) : UINT64_C(0x0001000100010001);
+    uint64_t random_mask = (full ^ keep) * lanes;
+    size_t bytes = (size_t)(range + bias + mask) * width;
+    unsigned char *dest = (unsigned char *)fingerprints;
+    while (bytes) {
+      uint64_t word = binary_fuse_rng_splitmix64(&seed) & random_mask;
+      size_t chunk = bytes < sizeof(word) ? bytes : sizeof(word);
+      memcpy(dest, &word, chunk);
+      dest += chunk;
+      bytes -= chunk;
+    }
+  }
+  uint16_t values[3 * BINARY_FUSE_CORE_LIMIT];
+  for (unsigned j = num_columns; j-- > 0;) {
+    uint32_t index = columns[j];
+    if (!basis[j]) {
+      values[j] = width == 1 ? ((uint8_t *)fingerprints)[index] :
+                               ((uint16_t *)fingerprints)[index];
+      continue;
+    }
+    uint16_t value = (uint16_t)(basis[j] & keep);
+    uint64_t others = basis[j] >> 16;
+    others &= others - 1;
+    while (others) {
+      value ^= values[binary_fuse_low_bit(others)];
+      others &= others - 1;
+    }
+    values[j] = value;
+    if (width == 1) ((uint8_t *)fingerprints)[index] = (uint8_t)value;
+    else ((uint16_t *)fingerprints)[index] = value;
+  }
+  return true;
+}
+
+static inline void binary_fuse_backfill(const uint64_t *cells, const uint32_t *queue,
+    uint32_t count, uint32_t keep, void *fingerprints, size_t width, bool short_table) {
+  while (count) {
+#if defined(__GNUC__) || defined(__clang__)
+    if (!short_table && count > BINARY_FUSE_LOOKAHEAD)
+      __builtin_prefetch(cells + queue[count - BINARY_FUSE_LOOKAHEAD - 1], 0, 1);
+#endif
+    uint32_t pivot = queue[--count];
+    uint64_t record = cells[pivot];
+    uint32_t b = binary_fuse_neighbor(pivot, (uint16_t)(record >> 32), short_table);
+    uint32_t c = binary_fuse_neighbor(pivot, (uint16_t)(record >> 48), short_table);
+    uint32_t tag = (uint32_t)(record >> 16) & keep;
+    if (width == 1) {
+      uint8_t *table = (uint8_t *)fingerprints;
+      table[pivot] = (uint8_t)tag ^ table[b] ^ table[c];
+    } else {
+      uint16_t *table = (uint16_t *)fingerprints;
+      table[pivot] = (uint16_t)tag ^ table[b] ^ table[c];
+    }
+  }
+}
+
+static inline bool binary_fuse_band_build(uint64_t *keys, uint32_t n, uint64_t *out_seed,
+    uint32_t range, uint32_t span, uint32_t bias, void *fingerprints, size_t width,
+    uint64_t *out_fields) {
+  uint32_t length = range + bias + span - 1, mask = span - 1;
+  if ((uint64_t)length * sizeof(uint64_t) > SIZE_MAX) return false;
+  bool tiled = n >= 262144;
+  uint32_t tiles = ((range - 1) >> BINARY_FUSE_TILE_BITS) + 1;
+  uint32_t *used = tiled ? (uint32_t *)malloc((size_t)tiles * sizeof(*used)) : NULL;
+  uint64_t *scratch = tiled ? (uint64_t *)malloc(BINARY_FUSE_TILE * sizeof(*scratch)) : NULL;
+  uint64_t *cells = (uint64_t *)malloc((size_t)length * sizeof(*cells));
+  uint32_t *queue = (uint32_t *)malloc(((size_t)length + 1) * sizeof(*queue));
+  bool success = false;
+  if (cells && queue && (!tiled || (used && scratch))) {
+    uint64_t state = UINT64_C(0x16375cf2ad81b049);
+    for (unsigned attempt = 0; attempt < XOR_MAX_ITERATIONS; ++attempt) {
+      uint64_t seed = attempt ? (binary_fuse_rng_splitmix64(&state) | 1) :
+                                BINARY_FUSE_INITIAL_MULTIPLIER;
+      if (attempt == 6) n = (uint32_t)binary_fuse_sort_and_remove_dup(keys, n);
+      if (tiled) {
+        binary_fuse_fill_tiled(keys, n, seed, range, length, mask, bias, cells,
+                               queue, used, tiles, scratch);
+      } else {
+        memset(cells, 0, (size_t)length * sizeof(*cells));
+        for (uint32_t i = 0; i < n; ++i) {
+          uint64_t hash = binary_fuse_band_hash(keys[i], seed);
+          binary_fuse_add_edge(cells, binary_fuse_band_start(hash, range),
+                               hash, mask, bias);
+        }
+      }
+      uint32_t end = 0;
+      uint64_t total_degree = 0;
+      for (uint32_t i = 0; i < length; ++i) {
+        uint16_t degree = (uint16_t)cells[i];
+        queue[end] = i;
+        end += degree == 1;
+        total_degree += degree;
+      }
+      if (total_degree != (uint64_t)n * 3) continue;
+      bool short_table = length <= 65536;
+      uint32_t count = binary_fuse_peel(cells, queue, end, short_table);
+      if (n - count > BINARY_FUSE_CORE_LIMIT) continue;
+      uint64_t fields = binary_fuse_fields(span, UINT16_MAX);
+      if (count < n) {
+        if (!binary_fuse_solve_core(keys, n, seed, range, mask, bias, cells,
+                                    fingerprints, width, &fields, n - count)) continue;
+      }
+      binary_fuse_backfill(cells, queue, count, (uint32_t)(fields >> 32),
+                           fingerprints, width, short_table);
+      *out_seed = seed;
+      *out_fields = fields;
+      success = true;
+      break;
+    }
+  }
+  free(queue);
+  free(cells);
+  free(scratch);
+  free(used);
+  return success;
+}
+
+#undef BINARY_FUSE_CORE_LIMIT
+#undef BINARY_FUSE_LOOKAHEAD
+#undef BINARY_FUSE_TILE
+#undef BINARY_FUSE_TILE_BITS
+#endif
